um(local_inst_net_miliar), 3) AS inst_net_30d, round(sum(local_retail_net_miliar), 3) AS retail_net_30d, round(sum(prime_foreign_net_miliar), 3) AS prime_net_30d, max(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('4 days' AS INTERVAL)))) THEN (foreign_buy_brokers) ELSE NULL END) AS foreign_buy_brokers_5d, max(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('4 days' AS INTERVAL)))) THEN (inst_buy_brokers) ELSE NULL END) AS inst_buy_brokers_5d, CASE  WHEN (((sum(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('4 days' AS INTERVAL)))) THEN (foreign_net_miliar) ELSE 0 END) > 0) AND (sum(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('19 days' AS INTERVAL)))) THEN (foreign_net_miliar) ELSE 0 END) > 0))) THEN ('CONSISTENT_BUY') WHEN ((sum(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('4 days' AS INTERVAL)))) THEN (foreign_net_miliar) ELSE 0 END) > 0)) THEN ('NEW_BUY') WHEN (((sum(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('4 days' AS INTERVAL)))) THEN (foreign_net_miliar) ELSE 0 END) < 0) AND (sum(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('19 days' AS INTERVAL)))) THEN (foreign_net_miliar) ELSE 0 END) < 0))) THEN ('CONSISTENT_SELL') WHEN ((sum(CASE  WHEN ((date >= ((SELECT d FROM max_dt) - CAST('4 days' AS INTERVAL)))) THEN (foreign_net_miliar) ELSE 0 END) < 0)) THEN ('NEW_SELL') ELSE 'MIXED' END AS foreign_trend_5d_vs_20d FROM base GROUP BY stock_code;

