-- main.vw_f_insider_events
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_f_insider_events AS SELECT i.transaction_date, i.stock_code, i.insider_id, i.insider_name, i.action_type, i.nationality, CASE  WHEN ((i.is_pengendali AND i.is_komisaris AND i.is_direksi)) THEN ('PENGENDALI_KOMISARIS_DIREKSI') WHEN ((i.is_pengendali AND i.is_komisaris)) THEN ('PENGENDALI_KOMISARIS') WHEN ((i.is_pengendali AND i.is_direksi)) THEN ('PENGENDALI_DIREKSI') WHEN (i.is_pengendali) THEN ('PENGENDALI') WHEN ((i.is_komisaris AND i.is_direksi)) THEN ('KOMISARIS_DIREKSI') WHEN (i.is_komisaris) THEN ('KOMISARIS') WHEN (i.is_direksi) THEN ('DIREKSI') ELSE 'MAJOR_HOLDER' END AS role_label, CASE  WHEN (i.is_pengendali) THEN (3) WHEN ((i.is_komisaris OR i.is_direksi)) THEN (2) ELSE 1 END AS role_weight, i.is_pengendali, i.is_komisaris, i.is_direksi, i.shares_change, i.pct_change, i.pct_previous, i.pct_current, i.shares_current, i.price_formatted AS price_at_transaction, CASE  WHEN ((i.price_formatted > 0)) THEN ((abs(i.shares_change) * i.price_formatted)) ELSE NULL END AS est_value_idr, CASE  WHEN ((i.price_formatted > 0)) THEN (round(((abs(i.shares_change) * i.price_formatted) / 1000000000.0), 3)) ELSE NULL END AS est_value_miliar, CASE  WHEN ((abs(i.pct_change) >= 1.0)) THEN ('LARGE') WHEN ((abs(i.pct_change) >= 0.1)) THEN ('MEDIUM') ELSE 'SMALL' END AS transaction_size, i.broker_code, i.broker_group, i.source_type, i.badges, CAST((CURRENT_DATE - i.transaction_date) AS INTEGER) AS days_ago, CASE  WHEN ((CAST((CURRENT_DATE - i.transaction_date) AS INTEGER) <= 7)) THEN ('THIS_WEEK') WHEN ((CAST((CURRENT_DATE - i.transaction_date) AS INTEGER) <= 30)) THEN ('THIS_MONTH') WHEN ((CAST((CURRENT_DATE - i.transaction_date) AS INTEGER) <= 90)) THEN ('LAST_3M') ELSE 'OLDER' END AS recency_label, ((i.is_pengendali OR i.is_komisaris OR i.is_direksi) AND (abs(i.pct_change) >= 0.1)) AS is_high_conviction, COALESCE(cp.sector, 'Others') AS sector, COALESCE(cp.group_name, 'Others') AS group_name, cp.free_float FROM main.insider_major_holder AS i LEFT JOIN market.company_profile AS cp ON ((i.stock_code = cp.stock_code));

-- ─────────────────────────────────────────────────────────────
-- main.vw_f_insider_rolling
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_f_insider_rolling AS SELECT stock_code, count_star() FILTER (WHERE (days_ago <= 7)) AS tx_count_7d, count_star() FILTER (WHERE ((days_ago <= 7) AND (action_type = 'BUY'))) AS buy_count_7d, sum(est_value_miliar) FILTER (WHERE ((days_ago <= 7) AND (action_type = 'BUY'))) AS buy_value_7d_miliar, count_star() FILTER (WHERE (days_ago <= 30)) AS tx_count_30d, count_star() FILTER (WHERE ((days_ago <= 30) AND (action_type = 'BUY'))) AS buy_count_30d, count_star() FILTER (WHERE ((days_ago <= 30) AND (action_type = 'SELL'))) AS sell_count_30d, count(DISTINCT insider_id) FILTER (WHERE ((days_ago <= 30) AND (action_type = 'BUY'))) AS unique_buyers_30d, count(DISTINCT insider_id) FILTER (WHERE ((days_ago <= 30) AND (action_type = 'SELL'))) AS unique_sellers_30d, sum(est_value_miliar) FILTER (WHERE ((days_ago <= 30) AND (action_type = 'BUY'))) AS buy_value_30d_miliar, sum(est_value_miliar) FILTER (WHERE ((days_ago <= 30) AND (action_type = 'SELL'))) AS sell_value_30d_miliar, sum(shares_change) FILTER (WHERE (days_ago <= 30)) AS net_shares_30d, count_star() FILTER (WHERE (days_ago <= 90)) AS tx_count_90d, sum(shares_change) FILTER (WHERE (days_ago <= 90)) AS net_shares_90d, count_star() FILTER (WHERE (is_high_conviction AND (days_ago <= 30) AND (action_type = 'BUY'))) AS hc_buy_30d, count_star() FILTER (WHERE (is_high_conviction AND (days_ago <= 30) AND (action_type = 'SELL'))) AS hc_sell_30d, count_star() FILTER (WHERE (is_pengendali AND (days_ago <= 30) AND (action_type = 'BUY'))) AS pengendali_buy_30d, count_star() FILTER (WHERE (is_pengendali AND (days_ago <= 30) AND (action_type = 'SELL'))) AS pengendali_sell_30d, max(transaction_date) AS last_tx_date, min(transaction_date) FILTER (WHERE ((days_ago <= 30) AND (action_type = 'BUY'))) AS first_buy_date_30d, count(DISTINCT insider_id) FILTER (WHERE ((days_ago <= 14) AND (action_type = 'BUY'))) AS cluster_buyers_14d, CASE  WHEN ((sum(shares_change) FILTER (WHERE (days_ago <= 30)) > 0)) THEN ('ACCUMULATING') WHEN ((sum(shares_change) FILTER (WHERE (days_ago <= 30)) < 0)) THEN ('DISTRIBUTING') ELSE 'NEUTRAL' END AS direction_30d, CASE  WHEN ((count_star() FILTER (WHERE (is_pengendali AND (days_ago <= 30) AND (action_type = 'BUY'))) > 0)) THEN ('HIGH') WHEN ((count_star() FILTER (WHERE (is_high_conviction AND (days_ago <= 30) AND (action_type = 'BUY'))) > 0)) THEN ('MEDIUM') WHEN ((count_star() FILTER (WHERE ((days_ago <= 30) AND (action_type = 'BUY'))) > 0)) THEN ('LOW') ELSE 'NONE' END AS conviction_tier FROM main.vw_f_insider_events GROUP BY stock_code;

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_activity_feed
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_activity_feed AS WITH base AS (SELECT i.*, COALESCE((i.shares_current - lag(i.shares_current) OVER (PARTITION BY i.stock_code, i.insider_name ORDER BY i.transaction_date, i.shares_current)), i.shares_change) AS sc_corr, COALESCE(round((i.pct_current - lag(i.pct_current) OVER (PARTITION BY i.stock_code, i.insider_name ORDER BY i.transaction_date, i.shares_current)), 4), i.pct_change) AS pc_corr, COALESCE(lag(i.pct_current) OVER (PARTITION BY i.stock_code, i.insider_name ORDER BY i.transaction_date, i.shares_current), i.pct_previous) AS pp_corr FROM main.vw_insider_clean AS i)SELECT i.transaction_date, i.stock_code, i.insider_name, i.insider_id, i.action_type, i.nationality, i.sc_corr AS shares_change, i.pc_corr AS pct_change, i.pp_corr AS pct_previous, i.pct_current, i.shares_current, i.price_formatted, i.broker_code, i.broker_group, i.source_type, i.badges, i.is_pengendali, i.is_komisaris, i.is_direksi, CASE  WHEN (i.is_pengendali) THEN ('PENGENDALI') WHEN (i.is_komisaris) THEN ('KOMISARIS') WHEN (i.is_direksi) THEN ('DIREKSI') WHEN ((i.badges != '')) THEN (i.badges) ELSE 'MAJOR HOLDER' END AS insider_type, CASE  WHEN (i.is_pengendali) THEN (3) WHEN ((i.is_komisaris OR i.is_direksi)) THEN (2) ELSE 1 END AS insider_weight, CASE  WHEN ((abs(i.pc_corr) >= 1.0)) THEN ('LARGE') WHEN ((abs(i.pc_corr) >= 0.1)) THEN ('MEDIUM') ELSE 'SMALL' END AS transaction_size, CASE  WHEN ((i.price_formatted > 0)) THEN ((abs(i.sc_corr) * i.price_formatted)) ELSE NULL END AS est_transaction_value, CASE  WHEN ((i.price_formatted > 0)) THEN (round(((abs(i.sc_corr) * i.price_formatted) / 1000000000.0), 3)) ELSE NULL END AS est_value_miliar, CASE  WHEN (((i.is_komisaris OR i.is_direksi OR i.is_pengendali) AND (abs(i.pc_corr) >= 0.1))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS is_insider_alert, CAST((CURRENT_DATE - i.transaction_date) AS INTEGER) AS days_ago, CASE  WHEN (((CURRENT_DATE - i.transaction_date) <= 7)) THEN ('THIS WEEK') WHEN (((CURRENT_DATE - i.transaction_date) <= 30)) THEN ('THIS MONTH') WHEN (((CURRENT_DATE - i.transaction_date) <= 90)) THEN ('LAST 3 MONTHS') ELSE 'OLDER' END AS recency_label FROM base AS i;

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_alert_feed
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_alert_feed AS SELECT i.transaction_date, i.stock_code, i.insider_name, CASE  WHEN (i.is_pengendali) THEN ('PENGENDALI') WHEN (i.is_komisaris) THEN ('KOMISARIS') WHEN (i.is_direksi) THEN ('DIREKSI') ELSE 'MAJOR HOLDER' END AS insider_type, i.action_type, i.shares_change, i.pct_change, i.pct_previous, i.pct_current, i.price_formatted, i.broker_code, i.broker_group, CASE  WHEN (((abs(i.pct_change) >= 1.0) OR ((i.is_pengendali OR i.is_komisaris OR i.is_direksi) AND (abs(i.pct_change) >= 0.1)))) THEN ('🔴 HIGH') WHEN ((abs(i.pct_change) >= 0.3)) THEN ('🟡 MEDIUM') ELSE '🟢 LOW' END AS alert_level, CASE  WHEN ((i.price_formatted > 0)) THEN (round(((abs(i.shares_change) * i.price_formatted) / 1000000000.0), 3)) ELSE NULL END AS est_value_miliar, CAST((CURRENT_DATE - i.transaction_date) AS INTEGER) AS days_ago, mkt."close" AS current_price, mkt.sector, mkt.signal AS market_signal, mkt.group_name FROM main.vw_insider_clean AS i LEFT JOIN market.vw_stock_latest AS mkt ON ((i.stock_code = mkt.stock_code)) WHERE ((abs(i.pct_change) >= 0.3) OR i.is_pengendali OR i.is_komisaris OR i.is_direksi) ORDER BY i.transaction_date DESC, abs(i.pct_change) DESC;

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_clean
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_clean AS SELECT * FROM main.insider_major_holder WHERE ((pct_current BETWEEN 0 AND 100) AND (abs(pct_change) <= 5));

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_conviction_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_conviction_score AS WITH scored AS (SELECT stock_code, max(transaction_date) AS latest_tx, count_star() AS total_tx, sum(((CASE  WHEN ((action_type = 'BUY')) THEN (1) ELSE -1 END * CASE  WHEN (is_pengendali) THEN (3) WHEN ((is_komisaris OR is_direksi)) THEN (2) ELSE 1 END) * CASE  WHEN ((abs(pct_change) >= 1.0)) THEN (3) WHEN ((abs(pct_change) >= 0.1)) THEN (2) ELSE 1 END)) AS score_alltime, sum(CASE  WHEN ((transaction_date >= (CURRENT_DATE - 30))) THEN ((((CASE  WHEN ((action_type = 'BUY')) THEN (1) ELSE -1 END * CASE  WHEN (is_pengendali) THEN (3) WHEN ((is_komisaris OR is_direksi)) THEN (2) ELSE 1 END) * CASE  WHEN ((abs(pct_change) >= 1.0)) THEN (3) WHEN ((abs(pct_change) >= 0.1)) THEN (2) ELSE 1 END) * 2)) ELSE 0 END) AS score_30d, count_star() FILTER (WHERE ((is_komisaris OR is_direksi OR is_pengendali) AND (action_type = 'BUY'))) AS internal_buy, count_star() FILTER (WHERE ((is_komisaris OR is_direksi OR is_pengendali) AND (action_type = 'SELL'))) AS internal_sell FROM main.vw_insider_clean GROUP BY stock_code)SELECT stock_code, latest_tx, total_tx, internal_buy, internal_sell, score_alltime, score_30d, ((score_alltime + score_30d) + CASE  WHEN (((internal_buy > 0) AND (internal_sell = 0))) THEN (5) WHEN (((internal_sell > 0) AND (internal_buy = 0))) THEN (-5) ELSE 0 END) AS conviction_score, CASE  WHEN ((((score_alltime + score_30d) + CASE  WHEN (((internal_buy > 0) AND (internal_sell = 0))) THEN (5) WHEN (((internal_sell > 0) AND (internal_buy = 0))) THEN (-5) ELSE 0 END) >= 15)) THEN ('🟢 STRONG ACCUMULATE') WHEN ((((score_alltime + score_30d) + CASE  WHEN (((internal_buy > 0) AND (internal_sell = 0))) THEN (5) WHEN (((internal_sell > 0) AND (internal_buy = 0))) THEN (-5) ELSE 0 END) >= 5)) THEN ('🟡 ACCUMULATE') WHEN ((((score_alltime + score_30d) + CASE  WHEN (((internal_buy > 0) AND (internal_sell = 0))) THEN (5) WHEN (((internal_sell > 0) AND (internal_buy = 0))) THEN (-5) ELSE 0 END) >= -4)) THEN ('⚪ NEUTRAL') WHEN ((((score_alltime + score_30d) + CASE  WHEN (((internal_buy > 0) AND (internal_sell = 0))) THEN (5) WHEN (((internal_sell > 0) AND (internal_buy = 0))) THEN (-5) ELSE 0 END) >= -14)) THEN ('🟠 DISTRIBUTE') ELSE '🔴 STRONG DISTRIBUTE' END AS insider_signal, CASE  WHEN (((latest_tx >= (CURRENT_DATE - 30)) AND (internal_buy > 0))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS fresh_internal_buy, CASE  WHEN (((latest_tx >= (CURRENT_DATE - 30)) AND (internal_sell > 0))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS fresh_internal_sell FROM scored;

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_latest_position
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_latest_position AS WITH ranked AS (SELECT *, row_number() OVER (PARTITION BY insider_id, stock_code ORDER BY transaction_date DESC) AS rn FROM main.vw_insider_clean)SELECT r.stock_code, r.insider_id, r.insider_name, r.transaction_date AS last_transaction_date, r.action_type AS last_action, r.pct_current AS current_pct_holding, r.shares_current AS current_shares, r.pct_change AS last_pct_change, r.shares_change AS last_shares_change, r.price_formatted AS last_price, r.is_pengendali, r.is_komisaris, r.is_direksi, r.badges, r.broker_group, r.nationality, CASE  WHEN (r.is_pengendali) THEN ('PENGENDALI') WHEN (r.is_komisaris) THEN ('KOMISARIS') WHEN (r.is_direksi) THEN ('DIREKSI') ELSE 'MAJOR HOLDER' END AS insider_type, CAST((CURRENT_DATE - r.transaction_date) AS INTEGER) AS days_since_last_tx FROM ranked AS r WHERE (r.rn = 1);

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_net_flow_by_stock
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_net_flow_by_stock AS SELECT stock_code, count_star() AS total_transactions, count_star() FILTER (WHERE (action_type = 'BUY')) AS total_buy_count, count_star() FILTER (WHERE (action_type = 'SELL')) AS total_sell_count, sum(CASE  WHEN ((action_type = 'BUY')) THEN (shares_change) ELSE 0 END) AS total_shares_bought, sum(CASE  WHEN ((action_type = 'SELL')) THEN (abs(shares_change)) ELSE 0 END) AS total_shares_sold, sum(shares_change) AS net_shares_change, round(CAST(sum(pct_change) AS "DOUBLE"), 4) AS net_pct_change, count(DISTINCT insider_id) AS unique_insiders, count(DISTINCT insider_id) FILTER (WHERE (action_type = 'BUY')) AS unique_buyers, count(DISTINCT insider_id) FILTER (WHERE (action_type = 'SELL')) AS unique_sellers, max(transaction_date) AS latest_tx_date, min(transaction_date) AS earliest_tx_date, count_star() FILTER (WHERE (transaction_date >= (CURRENT_DATE - 30))) AS tx_last30d, count_star() FILTER (WHERE ((transaction_date >= (CURRENT_DATE - 30)) AND (action_type = 'BUY'))) AS buy_30d, count_star() FILTER (WHERE ((transaction_date >= (CURRENT_DATE - 30)) AND (action_type = 'SELL'))) AS sell_30d, sum(shares_change) FILTER (WHERE (transaction_date >= (CURRENT_DATE - 30))) AS net_shares_30d, round(CAST(sum(pct_change) FILTER (WHERE (transaction_date >= (CURRENT_DATE - 30))) AS "DOUBLE"), 4) AS net_pct_30d, count(DISTINCT insider_id) FILTER (WHERE (transaction_date >= (CURRENT_DATE - 30))) AS unique_insiders_30d, count_star() FILTER (WHERE (transaction_date >= (CURRENT_DATE - 7))) AS tx_last7d, sum(shares_change) FILTER (WHERE (transaction_date >= (CURRENT_DATE - 7))) AS net_shares_7d, count_star() FILTER (WHERE (is_komisaris OR is_direksi OR is_pengendali)) AS insider_internal_tx, sum(shares_change) FILTER (WHERE (is_komisaris OR is_direksi OR is_pengendali)) AS insider_internal_net_shares, count_star() FILTER (WHERE ((is_komisaris OR is_direksi OR is_pengendali) AND (action_type = 'BUY'))) AS internal_buy_count, count_star() FILTER (WHERE ((is_komisaris OR is_direksi OR is_pengendali) AND (action_type = 'SELL'))) AS internal_sell_count, round(((CAST(count_star() FILTER (WHERE (action_type = 'BUY')) AS "DOUBLE") / "nullif"(count_star(), 0)) * 100), 1) AS buy_pressure_pct, CASE  WHEN ((sum(shares_change) > 0)) THEN ('ACCUMULATING') WHEN ((sum(shares_change) < 0)) THEN ('DISTRIBUTING') ELSE 'NEUTRAL' END AS overall_direction, CASE  WHEN ((sum(shares_change) FILTER (WHERE (transaction_date >= (CURRENT_DATE - 30))) > 0)) THEN ('ACCUMULATING') WHEN ((sum(shares_change) FILTER (WHERE (transaction_date >= (CURRENT_DATE - 30))) < 0)) THEN ('DISTRIBUTING') ELSE 'NEUTRAL' END AS direction_30d FROM main.vw_insider_clean GROUP BY stock_code;

-- ─────────────────────────────────────────────────────────────
-- main.vw_insider_with_market
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_insider_with_market AS SELECT cs.stock_code, cs.conviction_score, cs.insider_signal, cs.latest_tx AS last_insider_date, cs.total_tx AS insider_tx_count, cs.internal_buy, cs.internal_sell, cs.fresh_internal_buy, cs.fresh_internal_sell, nf.overall_direction, nf.direction_30d, nf.buy_pressure_pct, nf.net_pct_change AS net_pct_alltime, nf.net_pct_30d, nf.unique_insiders, nf.tx_last30d, nf.tx_last7d, nf.insider_internal_tx, mkt.sector, mkt."close" AS current_price, mkt.change_percent AS price_change_pct, mkt.whale_signal, mkt.big_player_anomaly, mkt.signal AS market_signal, mkt.free_float, mkt.group_name, mkt.vwma_20d, mkt.net_foreign_value, mkt.aov_ratio_ma20, CASE  WHEN (((cs.insider_signal ~~ '%STRONG ACCUMULATE%') AND (mkt.signal IN ('BUY', 'STRONG BUY')))) THEN ('⚡ CONFLUENCE BUY') WHEN (((cs.insider_signal ~~ '%STRONG DISTRIBUTE%') AND (mkt.signal IN ('SELL', 'STRONG SELL')))) THEN ('⚡ CONFLUENCE SELL') WHEN ((cs.insider_signal ~~ '%STRONG ACCUMULATE%')) THEN ('🟢 INSIDER STRONG BUY') WHEN ((cs.insider_signal ~~ '%ACCUMULATE%')) THEN ('📈 INSIDER BUY') WHEN ((cs.insider_signal ~~ '%STRONG DISTRIBUTE%')) THEN ('🔴 INSIDER STRONG SELL') WHEN ((cs.insider_signal ~~ '%DISTRIBUTE%')) THEN ('📉 INSIDER SELL') ELSE '— WATCH' END AS composite_signal FROM main.vw_insider_conviction_score AS cs LEFT JOIN main.vw_insider_net_flow_by_stock AS nf ON ((cs.stock_code = nf.stock_code)) LEFT JOIN market.vw_stock_latest AS mkt ON ((cs.stock_code = mkt.stock_code));

-- ─────────────────────────────────────────────────────────────
-- main.vw_s_insider_buying
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_s_insider_buying AS SELECT ir.stock_code, ir.tx_count_30d, ir.buy_count_30d, ir.sell_count_30d, ir.unique_buyers_30d, ir.unique_sellers_30d, ir.buy_value_30d_miliar, ir.sell_value_30d_miliar, ir.net_shares_30d, ir.hc_buy_30d, ir.hc_sell_30d, ir.pengendali_buy_30d, ir.pengendali_sell_30d, ir.last_tx_date, ir.direction_30d, ir.conviction_tier, ir.cluster_buyers_14d, (ir.buy_count_30d > 0) AS has_insider_buy_30d, ((ir.buy_count_30d > 0) AND (CAST((CURRENT_DATE - ir.last_tx_date) AS INTEGER) <= 7)) AS has_insider_buy_7d, (ir.cluster_buyers_14d >= 2) AS is_cluster_buy, CASE  WHEN ((ir.pengendali_buy_30d > 0)) THEN ('PENGENDALI') WHEN ((ir.hc_buy_30d > 0)) THEN ('KOMISARIS_DIREKSI') WHEN ((ir.buy_count_30d > 0)) THEN ('MAJOR_HOLDER') ELSE 'NONE' END AS buyer_role, least(10, greatest(-10, (((((ir.buy_count_30d - ir.sell_count_30d) + (ir.pengendali_buy_30d * 2)) + ir.hc_buy_30d) - (ir.pengendali_sell_30d * 2)) - ir.hc_sell_30d))) AS insider_direction_score, ir.buy_value_7d_miliar, ir.tx_count_7d FROM main.vw_f_insider_rolling AS ir;

-- ─────────────────────────────────────────────────────────────
-- main.vw_s_insider_cluster
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_s_insider_cluster AS WITH cluster_base AS (SELECT stock_code, action_type, count(DISTINCT insider_id) AS unique_insiders, count(DISTINCT role_label) AS unique_roles, sum(est_value_miliar) AS total_value_miliar, min(transaction_date) AS cluster_start, max(transaction_date) AS cluster_end, CAST((max(transaction_date) - min(transaction_date)) AS INTEGER) AS cluster_span_days, max(CASE  WHEN ((role_label ~~ '%PENGENDALI%')) THEN (1) ELSE 0 END) AS has_pengendali, max(CASE  WHEN ((role_label ~~ '%KOMISARIS%')) THEN (1) ELSE 0 END) AS has_komisaris, max(CASE  WHEN ((role_label ~~ '%DIREKSI%')) THEN (1) ELSE 0 END) AS has_direksi FROM main.vw_f_insider_events WHERE (days_ago <= 30) GROUP BY stock_code, action_type)SELECT b.stock_code, max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.unique_insiders) ELSE NULL END) AS buy_cluster_size, max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.total_value_miliar) ELSE NULL END) AS buy_cluster_value_miliar, max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.has_pengendali) ELSE NULL END) AS buy_has_pengendali, max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.unique_roles) ELSE NULL END) AS buy_unique_roles, max(CASE  WHEN ((b.action_type = 'SELL')) THEN (b.unique_insiders) ELSE NULL END) AS sell_cluster_size, max(CASE  WHEN ((b.action_type = 'SELL')) THEN (b.total_value_miliar) ELSE NULL END) AS sell_cluster_value_miliar, CASE  WHEN (((max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.unique_insiders) ELSE 0 END) >= 2) AND (max(CASE  WHEN ((b.action_type = 'SELL')) THEN (b.unique_insiders) ELSE 0 END) = 0))) THEN ('PURE_CLUSTER_BUY') WHEN ((max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.unique_insiders) ELSE 0 END) >= 2)) THEN ('CLUSTER_BUY') WHEN (((max(CASE  WHEN ((b.action_type = 'SELL')) THEN (b.unique_insiders) ELSE 0 END) >= 2) AND (max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.unique_insiders) ELSE 0 END) = 0))) THEN ('PURE_CLUSTER_SELL') WHEN ((max(CASE  WHEN ((b.action_type = 'SELL')) THEN (b.unique_insiders) ELSE 0 END) >= 2)) THEN ('CLUSTER_SELL') ELSE 'NO_CLUSTER' END AS cluster_type FROM cluster_base AS b GROUP BY b.stock_code HAVING ((max(CASE  WHEN ((b.action_type = 'BUY')) THEN (b.unique_insiders) ELSE 0 END) >= 2) OR (max(CASE  WHEN ((b.action_type = 'SELL')) THEN (b.unique_insiders) ELSE 0 END) >= 2));

-- ─────────────────────────────────────────────────────────────
-- main.vw_s_insider_vs_price
-- ─────────────────────────────────────────────────────────────
CREATE VIEW vw_s_insider_vs_price AS WITH insider_price AS (SELECT ie.stock_code, ie.transaction_date, ie.action_type, ie.role_label, ie.est_value_miliar, ie.is_high_conviction, ie.days_ago, ph.return_5d AS price_5d_before_tx, ph.return_20d AS price_20d_before_tx, ph.pct_from_52w_high AS pct_from_high_at_tx FROM main.vw_f_insider_events AS ie LEFT JOIN market.vw_f_price_history AS ph ON (((ie.stock_code = ph.stock_code) AND (ie.transaction_date = ph.trading_date))) WHERE (ie.days_ago <= 90))SELECT stock_code, count_star() FILTER (WHERE ((action_type = 'BUY') AND (price_20d_before_tx < -5.0))) AS bought_after_20d_decline, count_star() FILTER (WHERE ((action_type = 'BUY') AND (pct_from_high_at_tx < -30.0))) AS bought_near_52w_low, count_star() FILTER (WHERE ((action_type = 'SELL') AND (pct_from_high_at_tx > -10.0))) AS sold_near_52w_high, round(avg(price_20d_before_tx) FILTER (WHERE (action_type = 'BUY')), 2) AS avg_price_context_at_buy, (max(CASE  WHEN (((action_type = 'BUY') AND (price_20d_before_tx < -5.0))) THEN (1) ELSE 0 END) = 1) AS has_dip_buy, CASE  WHEN ((max(CASE  WHEN (((action_type = 'BUY') AND (price_20d_before_tx < -10.0))) THEN (1) ELSE 0 END) = 1)) THEN ('ULTRA_HIGH') WHEN ((max(CASE  WHEN (((action_type = 'BUY') AND (price_20d_before_tx < -5.0))) THEN (1) ELSE 0 END) = 1)) THEN ('HIGH') WHEN ((max(CASE  WHEN ((action_type = 'BUY')) THEN (1) ELSE 0 END) = 1)) THEN ('MEDIUM') ELSE 'LOW_OR_NONE' END AS price_conviction_label FROM insider_price GROUP BY stock_code;
